insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"LOSER_BUCKET","title":"¿Cuántas anota el perdedor?","description":"Elige el rango. Se corrige con el marcador final.","category":"marcador","difficulty":"hard","points":6,"answerType":"multiple","options":[{"id":"0a1","label":"0 o 1"},{"id":"2a3","label":"2 o 3"},{"id":"4a5","label":"4 o 5"},{"id":"6p","label":"6 o más"}],"rule":{"op":"buckets","fact":"loser_runs","buckets":[{"id":"0a1","label":"0 o 1","min":0,"max":1},{"id":"2a3","label":"2 o 3","min":2,"max":3},{"id":"4a5","label":"4 o 5","min":4,"max":5},{"id":"6p","label":"6 o más","min":6,"max":null}]},"priority":1,"cooldown":2,"tags":["marcador","rango"]},{"code":"BOTH_GTE_1","title":"¿Los dos equipos van a anotar?","description":"Se corrige con el marcador final.","category":"marcador","difficulty":"easy","points":2,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"both_gte","n":1},"priority":0,"cooldown":2,"tags":["marcador"]},{"code":"BOTH_GTE_2","title":"¿Ambos equipos anotarán al menos 2?","description":"Se corrige con el marcador final.","category":"ofensiva","difficulty":"easy","points":2,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"both_gte","n":2},"priority":0,"cooldown":2,"tags":["ofensiva"]},{"code":"BOTH_GTE_3","title":"¿Ambos equipos anotarán al menos 3?","description":"Se corrige con el marcador final.","category":"ofensiva","difficulty":"medium","points":4,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"both_gte","n":3},"priority":0,"cooldown":2,"tags":["ofensiva"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;